import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Operate devices through the same Entity detail","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/device-details","contentType":"tutorial","prev":{"text":"Spatial workbench","link":"/en/tutorials/spatial-workbench"},"next":{"text":"Device trends","link":"/en/tutorials/device-trends"}},"headers":[],"relativePath":"en/tutorials/device-details.md","filePath":"en/tutorials/device-details.md"}'),n={name:"en/tutorials/device-details.md"};function i(o,e,c,l,p,d){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="operate-devices-through-the-same-entity-detail" tabindex="-1">Operate devices through the same Entity detail <a class="header-anchor" href="#operate-devices-through-the-same-entity-detail" aria-label="Permalink to &quot;Operate devices through the same Entity detail&quot;">​</a></h1><p>Goal: select an Entity in the 3D space. Separate targets, actual observations, Commands and Task results. Recover a failed source restart.</p><h2 id="starting-state-and-source" tabindex="-1">Starting state and source <a class="header-anchor" href="#starting-state-and-source" aria-label="Permalink to &quot;Starting state and source&quot;">​</a></h2><p>Complete <a href="./spatial-workbench">Spatial workbench</a> first. Use the current checkout containing this chapter. Prepare a persistent Lab, two simulated lights and two simulated centrifuges. A Member needs a valid session. An Agent uses the same public interfaces with a valid <code>lab:full</code> key.</p><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>. The 3D space opens first after login. Start, Stop and actions below write to the development database.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/entity-detail.tsx" target="_blank" rel="noreferrer">shared detail</a> provides Operations, Records and Details. The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/workbench-context.tsx" target="_blank" rel="noreferrer">workbench context</a> retains targets and attempts per deployment, identity, Lab and Entity. The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/observation-state.ts" target="_blank" rel="noreferrer">property reader</a> reads server facts. It does not infer actual values from heartbeats. Devices use the existing <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/sdk/src/generated/sdk.gen.ts" target="_blank" rel="noreferrer">generated SDK</a>. This chapter adds no API.</p><h2 id="separate-targets-from-actual-values-in-operations" tabindex="-1">Separate targets from actual values in Operations <a class="header-anchor" href="#separate-targets-from-actual-values-in-operations" aria-label="Permalink to &quot;Separate targets from actual values in Operations&quot;">​</a></h2><ol><li><p>Open the object directory.</p></li><li><p>Select <code>Light A</code>.</p><p>The detail header shows its name, registered location, simulated source and identity type. <strong>Operations</strong> shows actual values, units, quality and times. A property without a report shows <strong>Unknown · No observation</strong>.</p></li><li><p>Select <strong>Start program</strong>.</p></li><li><p>Wait for the first observation.</p></li><li><p>Set <strong>Target brightness (%)</strong> to <code>23</code>.</p></li><li><p>Select <strong>Apply</strong>.</p><p>The Command shows submission, waiting and execution outcome. Reported brightness changes only when the server reports that property. Neither accepted nor succeeded replaces an actual observation.</p></li><li><p>Select <code>Light B</code>.</p></li><li><p>Set its target brightness to <code>77</code>.</p></li><li><p>Return to <code>Light A</code>.</p><p>A retains its target of <code>23</code>. B retains its own inputs and Command feedback. Selection changes do not turn targets into measurements. <strong>Requested power target</strong> retains the last request separately from <strong>Reported power</strong>.</p></li></ol><p>Targets and attempts remain in the current workbench session. Reloading reads persistent actual state. These inputs are not backend device configuration.</p><h2 id="check-current-and-last-reported-values" tabindex="-1">Check current and last reported values <a class="header-anchor" href="#check-current-and-last-reported-values" aria-label="Permalink to &quot;Check current and last reported values&quot;">​</a></h2><p>A property shows <strong>Current observation</strong> only when all these conditions hold:</p><ul><li>Its value matches the fixed definition type. <code>false</code> and <code>0</code> are valid. <code>null</code> and missing values remain unknown.</li><li>Property freshness is <code>current</code>, source time is known, and quality is <code>good</code>.</li><li>The property belongs to the current Binding and the current running Run.</li></ul><ol><li><p>Stop the program on <code>Light A</code>.</p><p>Reported values remain as <strong>Last reported value</strong>. Their original source and time remain. Stop does not switch the light off.</p></li><li><p>Start the program again.</p><p>The View shows a new Run. Properties without reports from that Run retain their last values. A brightness report cannot refresh the old power property. Neither can a heartbeat.</p></li><li><p>Open <strong>Details</strong>.</p><p>Check each property&#39;s Binding, Run, sequence, source time, receive time, update time, expiry, quality and original freshness. Current execution identities remain separate from each property&#39;s original identities.</p></li><li><p>Open <strong>Records</strong>.</p><p>Filter existing history for the same Entity. A history query does not change device state. See <a href="./run-history">Run history</a> for retention and public queries.</p></li></ol><h2 id="recover-sources-and-uncertain-commands" tabindex="-1">Recover sources and uncertain Commands <a class="header-anchor" href="#recover-sources-and-uncertain-commands" aria-label="Permalink to &quot;Recover sources and uncertain Commands&quot;">​</a></h2><ol><li><p>Select <strong>Restart source</strong> on a running device without an active Task.</p></li><li><p>Confirm the restart.</p><p>The View requests Stop first. It requests Start only after Stop succeeds. A failed Stop prevents Start. If Stop succeeds and Start fails, the source stays stopped. Select <strong>Start program</strong> to recover. A new Run does not resume an old Task or replay old actions.</p></li></ol><p>A lost response shows <strong>Submission uncertain</strong>. Retain the original parameters and key. Select <strong>Retry same command</strong>. For a known Command, select <strong>Refresh command</strong> to query its record. Do not automatically repeat actions with a new key. An old Run&#39;s action cannot replay in a new Run.</p><p>A connection failure or unavailable service retains the last snapshot and disables new operations. Reconnect, then confirm server state. Log in again after identity expiry or revocation. An old identity&#39;s attempts cannot be used by a new identity.</p><h2 id="complete-and-cancel-centrifuge-tasks" tabindex="-1">Complete and cancel centrifuge Tasks <a class="header-anchor" href="#complete-and-cancel-centrifuge-tasks" aria-label="Permalink to &quot;Complete and cancel centrifuge Tasks&quot;">​</a></h2><ol><li><p>Select <code>Centrifuge A</code>.</p></li><li><p>Start its program.</p></li><li><p>Set target speed to <code>6000 rpm</code>, target temperature to <code>22 degC</code>, and Task duration to <code>6 s</code>.</p></li><li><p>Select <strong>Start centrifuge</strong>.</p><p>The backend fixes Task parameters. Preparation does not count toward effective Task time. The backend starts timing after reaching tolerance. The Task then decelerates.</p></li><li><p>Wait for <strong>Completed</strong>.</p><p>The device returns to idle. The completed result remains visible. A new Run or later idle observation cannot replace an ended result.</p></li><li><p>Start a <code>60 s</code> Task on <code>Centrifuge B</code>.</p></li><li><p>Select <strong>Stop centrifuge</strong>.</p></li><li><p>Wait for deceleration to finish.</p><p>B&#39;s result becomes cancelled. A retains independent targets and results. <strong>Stop centrifuge</strong> cancels a Task. <strong>Stop program</strong> ends a Run. Cancel an active Task and wait for idle before stopping its source. See <a href="./centrifuge-tasks">Centrifuge Tasks</a> for ranges, backend stages and interruption recovery.</p></li></ol><h2 id="verify-and-continue" tabindex="-1">Verify and continue <a class="header-anchor" href="#verify-and-continue" aria-label="Permalink to &quot;Verify and continue&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-device-details.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-devices.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-centrifuges.test.tsx</span></span></code></pre></div><p>This entry operates actual Lab Views. MSW replaces HTTP only. Actual Node/Web browser acceptance uses separate services and persistent data. It checks desktop and approved narrow screens, actual WebGL pixels, focus and action targets. Tests do not use your active development database.</p><p>Continue with <a href="./device-trends">Device trends</a>. Read the same device’s historical values, gaps and sources.</p><hr><p>Source version：<code>c80e63c8c063</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/tutorials/device-details.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,27)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
